xml.Script:
        Col[0] := '9900EE'; // Purple
        Col[1] := 'FFFF00'; // Yellow
        Col[2] := 'FF8800'; // Orange
        Col[3] := 'FF0000'; // Red
        Col[4] := '00DD00'; // Green
        Col[5] := '0055FF'; // Blue

        for i := 0 to 23 do
            Colors[ i] := Col[i div 4];

        W  := 0.45;
        include 'Figures\Scripts\Deltoidal Icositetrahedron_Coordinates.inc'; // for axes

        A1 := ArcCos( s2 / 8 + 0.25);
        A2 := ArcCos( s2 / 4 - 0.5 );
        A3 := ArcCos(-s2 / 2 - 0.25); // = A1 + A2

        D := W * 1.12;
        DCut := W * 1.01;
